  const rng = SF.core.mulberry32((Math.floor(Math.random() * 2147483646) + 1) >>> 0);
  const between = (lo, hi) => lo + rng()*(hi - lo);
  const pick = arr => arr[Math.floor(rng()*arr.length)];

