      hullSlab(ctx, sd*62*A, 14*A, 44*A, 48*A, 9*A, pod, S);
      bloom(ctx, sd*62*A, 14*A, 28*A, "249,115,22", 0.35);
      ctx.fillStyle = "rgba(255,200,140,0.75)";
